const ARTICLES = [
  {"id": 1, "cat": "ulstur", "time": "15 мин", "timeEn": "15 min", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/2024-10-18%20Ulaanbaatar%2C%20S%C3%BCkhbaatar%20Square.jpg?width=1000", "title": "Улс тунхагласны 102 жилийн ой өнөөдөр тохиож байна", "titleEn": "102nd anniversary of the proclamation of the Republic marked today", "text": "Монгол Улс анхдугаар Үндсэн хуулиа баталж, Бүгд Найрамдах Монгол Ард Улсаа тунхагласны 102 жилийн ой өнөөдөр буюу арваннэгдүгээр сарын 26-нд тохиож байна. 1924 оны энэ өдөр батлагдсан анхны Үндсэн хууль нь Монголын төрт ёсны түүхэнд шинэ хуудас нээж, тусгаар тогтносон бүгд найрамдах улсын үндсийг тавьсан юм. Тэр цагаас хойш энэ өдрийг Улс тунхагласны баярын өдөр хэмээн тэмдэглэж, бүх нийтээр амардаг уламжлал тогтжээ.\nОйн өдрийг тохиолдуулан өнөөдөр Төрийн ордонд Монгол Улсын иргэний андгай өргөх ёслол болох бөгөөд Улсын Их Хурлын чуулганы нэгдсэн хуралдаан хуралдана. Мөн Монгол Улсын Ерөнхийлөгчийн ивээл дор зохион байгуулдаг “Тусгаар тогтнол” дүрслэх урлагийн үзэсгэлэн Монголын Урчуудын Эвлэлийн арт галерейд нээлтээ хийнэ. Чойжин ламын сүм музейд “Дуут өргөө” гэр тоглолт, Улсын драмын эрдмийн театрын тайзнаа “Тэнгэрийн хүү” жүжиг толилуулагдана.\nУлс тунхагласны ойд зориулсан чансаа өндөр 128 бөхийн барилдаан Монгол бөхийн өргөөнд өнөөдөр болно. Барилдаанд улсын аварга О.Хангай, улсын арслан Э.Оюунболд, Э.Батмагнай, Р.Пүрэвдагва тэргүүтэй улсын цолтой 44 бөх зодоглохоор бүртгүүлжээ. Түүнчлэн улсын харцага цолтой 14, улсын начин цолтой 19 бөх барилдах бөгөөд аймгийн цолтой бөхчүүдийг чансааны оноогоор эрэмбэлж барилдуулна.\nУлс тунхагласны өдөр нь зөвхөн түүхэн ой төдийгүй Монголын тусгаар тогтнол, үндэсний эв нэгдлийг эргэн санаж, ирээдүй хойч үедээ өвлүүлэх утга учиртай өдөр юм. Энэ өдөр улс орон даяар соёл, урлагийн арга хэмжээ зохион байгуулагдаж, иргэд гэр бүлээрээ амарч, баяраа тэмдэглэдэг уламжлалтай.", "textEn": "Today, November 26, marks the 102nd anniversary of Mongolia adopting its first Constitution and proclaiming the Mongolian People's Republic. The first Constitution, adopted on this day in 1924, opened a new chapter in Mongolian statehood and laid the foundations of an independent republic. Since then, the day has been celebrated as Republic Proclamation Day and observed as a public holiday.\nTo mark the occasion, a citizenship oath ceremony will be held at the State Palace today, and a plenary session of parliament will meet. The 'Independence' fine art exhibition, held under the auspices of the President of Mongolia, opens at the art gallery of the Mongolian Artists' Union. A 'Duut Urguu' ger concert will be performed at the Choijin Lama Temple Museum, and the play 'Son of Heaven' will be staged at the State Academic Drama Theatre.\nA high-ranking wrestling tournament for 128 wrestlers will also take place today at the Mongolian Wrestling Palace to mark the anniversary. State champion O. Khangai and state arslans E. Oyunbold, E. Batmagnai and R. Purevdagva are among the 44 state-titled wrestlers registered, along with 14 state khartsaga and 19 state nachin wrestlers. Provincial-titled wrestlers will be ranked by their rating points.\nRepublic Proclamation Day is more than a historical anniversary: it is a day to reflect on Mongolia's independence and national unity and to pass that legacy to future generations. Cultural events are held across the country, and families traditionally spend the holiday together."},
  {"id": 2, "cat": "ulstur", "time": "30 мин", "timeEn": "30 min", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Genghis%20Khan%2C%20Parliament%20Building%2C%20Ulaanbaatar%2C%20Mongolia%20%2848788605616%29.jpg?width=760", "title": "Намын удирдагчид Ерөнхийлөгчийн сонгуулийн асуудлаар ажлын хэсэг байгуулахаар тохиролцов", "titleEn": "Party leaders agree to form working group on presidential election", "text": "Улсын Их Хурлын дарга бөгөөд Ерөнхийлөгчийн үүргийг түр орлон гүйцэтгэгч С.Бямбацогтын зарлан хуралдуулсан намуудын удирдагчдын зөвлөлийн анхдугаар хуралдаан болж, Ерөнхийлөгчийн сонгуулийн асуудлаар ажлын хэсэг байгуулахаар тохиролцлоо. Хуралдаанд оролцсон намын удирдагчид шинэ Ерөнхийлөгч томилогдох хүртэл улс орны тогтвортой байдлыг хангахын төлөө хамтран ажиллахаа амлав.\nЕрөнхийлөгч У.Хүрэлсүх аравдугаар сарын 21-нд үүрэгт ажлаасаа чөлөөлөгдөх өргөдлөө өгч, Улсын Их Хурал 104 гишүүний 96-ийн саналаар чөлөөлсөн билээ. Тэрбээр Монголын түүхэнд бүрэн эрхээ хугацаанаас нь өмнө дуусгасан анхны Ерөнхийлөгч болсон юм. Хуульд Ерөнхийлөгчийн сонгуулийг үүрэгт ажлаас нь чөлөөлөгдсөнөөс хойш дөрвөн сарын дотор явуулахаар заасан байдаг.\nСонгуулийн ерөнхий хорооноос нөхцөл байдал нэгэнт тодорхой болсон учраас сонгуулийг даруй товлон зарлах ёстой гэж зөвлөсөн байна. Улсын Их Хурал энэ долоо хоногт багтаан сонгуулийн товыг тогтоохоор төлөвлөж байгаа бөгөөд санал хураалтыг хоёрдугаар сарын сүүлчээр эсвэл гуравдугаар сарын эхний долоо хоногт явуулахаар тооцоолж байна. Парламентад суудалтай таван нам, эвсэл нэр дэвшигчээ тодруулах эрхтэй.\nАжлын хэсэг нь сонгуулийн бэлтгэл, хугацаа, зохион байгуулалтын асуудлыг намуудын хооронд зөвшилцөх үүрэгтэй юм. Намууд нэгдүгээр сарын дундуур нэр дэвшигчээ тодруулж, санал авах өдрөөс 16 хоногийн өмнө сонгуулийн сурталчилгааг эхлүүлэхээр төлөвлөж байна.", "textEn": "The first meeting of a council of party leaders convened by Speaker and acting President S. Byambatsogt has agreed to form a working group on the presidential election. The party leaders at the meeting also pledged to work together to keep the country stable until a new president takes office.\nPresident U. Khurelsukh submitted his resignation on October 21, and parliament relieved him of office with 96 of 104 members voting in favour. He became the first sitting president in Mongolian history to leave office early. The law requires the presidential election to be held within four months of the president being relieved of office.\nThe General Election Commission has advised announcing the election promptly now that the situation is clear. Parliament plans to set the election date this week, with voting expected in late February or the first week of March. The five parties and coalitions holding seats in parliament are entitled to nominate candidates.\nThe working group will coordinate election preparations, timing and organisation between the parties. The parties plan to name their candidates in mid-January and start campaigning 16 days before polling day."},
  {"id": 3, "cat": "ulstur", "time": "45 мин", "timeEn": "45 min", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian%20Parliament%201.JPG?width=760", "title": "Шадар сайд Н.Номтойбаяр: Үндсэн хуулийн өөрчлөлт хийж “чөтгөрийн тойрог”-оосоо гарах ёстой", "titleEn": "Deputy PM N. Nomtoibayar: constitutional change needed to break the 'vicious circle'", "text": "Шадар сайд Н.Номтойбаяр цаг үеийн асуудлаар арваннэгдүгээр сарын 25-нд мэдээлэл өгөхдөө Үндсэн хуульд өөрчлөлт оруулж, “чөтгөрийн тойрог”-оосоо гарах ёстой гэж мэдэгдлээ. Тэрбээр энэ асуудлыг 2018 оноос хойш ярьж ирснээ онцолж, төрийн зөв тогтолцоог эргэж харах цаг болсон гэж үзэж байна.\nТүүний хэлснээр, Сонгуулийн ерөнхий хорооны гурван гишүүний бүрэн эрхийн хугацаа дуусчихсан байгаа нь хоёр асуудал үүсгэжээ. Нэгдүгээрт, хорооны гишүүдийг яаралтай томилох хэрэгтэй. Хоёрдугаарт, Үндсэн хуульд Ерөнхийлөгчийг зургаан жилийн хугацаатай сонгоно гэж заасан ч түүний бүрэн эрх дуусахад хагас жилийн хугацаа үлдэж байхад Улсын Их Хурлын дарга Ерөнхийлөгчийн бүрэн эрхийг хэрэгжүүлж байгаа нь маргаан дагуулж байна.\nШадар сайд мөн Үндэсний эвслийн талаар тайлбар хийлээ. Түүний хэлснээр, Үндэсний эвсэл бол улс төрийн нам биш, харин гурван нам нэгдэж байгуулсан эвсэл бөгөөд удирдах асуудлыг нь эвслийг бүрдүүлсэн намуудын удирдах зөвлөл, төлөөллийн байгууллагууд хамтын шийдвэрээр шийдвэрлэдэг байна. Ерөнхийлөгчийн сонгуулийн тухай хуульд эвслийг бүрдүүлсэн намуудын төлөөллийн байгууллага хуралдаж, шийдвэрээ гаргах ёстой гэж заасан байдаг.\nӨнөөдөр Төрийн байгуулалтын байнгын хороо хуралдаж, энэ асуудлыг хэлэлцэх юм. Тэрбээр мөн отроор өвөлжиж буй малчдын асуудлаар аймаг, сумдын удирдлагуудад чөлөөтэй шийдвэрлэх чиглэл өгсөн бөгөөд өвөлжилтийн бэлтгэлийг 21 аймгийн удирдлагуудтай дахин хэлэлцэнэ гэж мэдэгдлээ.", "textEn": "Deputy Prime Minister N. Nomtoibayar said on November 25 that Mongolia must amend its Constitution and break out of a 'vicious circle', speaking at a briefing on current affairs. He said he has raised the issue since 2018 and that the time has come to reconsider the country's system of government.\nAccording to him, the terms of three members of the General Election Commission have expired, creating two problems. First, the commission's members must be appointed urgently. Second, although the Constitution provides for a six-year presidential term, the Speaker of Parliament is exercising presidential powers with half a year of the term still remaining, which has caused dispute.\nThe deputy prime minister also explained the status of the National Coalition. He said it is not a political party but a coalition of three parties, whose leadership is decided jointly by the governing bodies and representative organisations of the constituent parties. The presidential election law requires the representative bodies of the constituent parties to meet and decide.\nThe Standing Committee on State Structure will meet today to discuss the matter. He also said provincial and district leaders have been given discretion over herders wintering in other areas, and that winter preparations will be discussed again with the leaders of all 21 provinces."},
  {"id": 4, "cat": "niigem", "time": "1 цаг", "timeEn": "1 hour", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Road%20in%20Mongolia%20aimak%20Bayan%20Ulgiy%2002.jpg?width=760", "title": "Өвөлжилтийн бэлтгэл хангалтгүй байна: Ерөнхий сайд 21 аймгийн удирдлагатай цахим хурал хийлээ", "titleEn": "Winter preparations fall short, prime minister tells provincial leaders", "text": "Монгол Улсын Ерөнхий сайд Н.Учрал 2026-2027 оны өвөл, хаваржилтын бэлтгэл ажлын хэрэгжилт, орон нутагт тулгамдаж буй асуудлаар 21 аймгийн удирдлагуудтай арваннэгдүгээр сарын 25-нд цахим хурал хийлээ. Хурлаар өвөлжилтийн бэлтгэлийн явц, тулгамдсан асуудлуудыг хэлэлцэж, үүрэг даалгавар өгөв.\nЕрөнхий сайд өвөлжилтийн бэлтгэлийн хүрээнд өгсөн үүрэг, даалгаврын хэрэгжилт 50 гаруй хувьтай байгаа нь хангалтгүй үзүүлэлт гэдгийг анхаарууллаа. Тэрбээр аймаг, орон нутгийн удирдлагуудад бэлтгэл ажлыг эрчимжүүлж, хугацаанд нь бүрэн хангахыг үүрэг болгов. Өвөлжилт хүндрэх эрсдэлтэй байгаа энэ үед малчид, иргэдийн амьдралд шууд нөлөөлөх бэлтгэл ажлыг орхигдуулж болохгүй гэж тэрбээр онцоллоо.\nАймаг, нийслэлийн хаврын улирлын хэрэгцээнд зориулан бүрдүүлэх 15-20 мянган тонн махны нөөц одоогоор 60 орчим хувийн гүйцэтгэлтэй байгаа бөгөөд тогтоосон хугацаанд бүрэн бүрдүүлэхийг холбогдох байгууллагуудад даалгав. Мөн мал эмнэлгийн үйлчилгээтэй холбоотой санхүүжилтийг орон нутгийн төсөвт бүрэн тусгаж, вакцинжуулалт, халдваргүйтгэлийг хугацаанд нь зохион байгуулахыг үүрэг болголоо.\n“Шинэ цагийн малчин” аяны хүрээнд малчдад өвс, тэжээлийн дэмжлэг үзүүлэх, малыг эдийн засгийн эргэлтэд оруулах ажлыг бодит үр дүнтэй хэрэгжүүлэхийг Ерөнхий сайд шаардав. Санхүүжилтээс болж шийдэгдэхгүй байгаа асуудлуудыг Сангийн сайдтай ярилцаж шийдвэрлэхээр болсон байна.", "textEn": "Prime Minister N. Uchral held an online meeting with the leaders of all 21 provinces on November 25 to discuss preparations for the 2026-2027 winter and spring season and pressing local issues. The meeting reviewed the progress of winter preparations and issued new instructions.\nThe prime minister warned that implementation of his instructions on winter preparations stands at just over 50 percent, which he called an unsatisfactory result. He instructed provincial and local leaders to step up preparations and complete them on time, stressing that work directly affecting herders and residents must not be neglected as the risk of a harsh winter grows.\nThe meat reserve of 15,000 to 20,000 tonnes for spring needs in the provinces and the capital is currently only about 60 percent complete, and the responsible bodies were told to finish it by the deadline. Veterinary funding must be fully reflected in local budgets, and vaccination and disinfection must be organised on schedule.\nUnder the 'New Era Herder' campaign, the prime minister demanded real results in providing herders with hay and fodder support and bringing livestock into economic circulation. Issues stalled for lack of funding will be resolved in discussion with the finance minister."},
  {"id": 5, "cat": "niigem", "time": "1 цаг", "timeEn": "1 hour", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Violence%20against%20women%20is%20not%20ok%20%286856711784%29.jpg?width=760", "title": "Жендэрт суурилсан хүчирхийлэлтэй тэмцэх 16 хоногийн аян “Хаана ч аюулгүй” уриан дор эхэллээ", "titleEn": "16-day campaign against gender-based violence begins under the slogan 'Safe Everywhere'", "text": "Жендэрт суурилсан хүчирхийлэлтэй тэмцэх 16 хоногийн аян “Хаана ч аюулгүй” уриан дор арваннэгдүгээр сарын 25-нд эхэллээ. Энэхүү аян нь жил бүр дэлхий даяар өрнөдөг хүчирхийллийн эсрэг 16 хоногийн олон улсын аяны нэг хэсэг бөгөөд эмэгтэйчүүд, хүүхдийн эсрэг хүчирхийллээс урьдчилан сэргийлэх, олон нийтийн мэдлэгийг дээшлүүлэх зорилготой юм.\nАяны хүрээнд төрийн байгууллагууд, иргэний нийгмийн байгууллагууд, хэвлэл мэдээллийн хэрэгслүүд хамтран хүчирхийллийн хор уршиг, хохирогчдод үзүүлэх тусламж, хууль эрх зүйн хамгааллын талаар олон нийтэд мэдээлэл хүргэхээр төлөвлөж байна. Хүчирхийлэлд өртсөн хүмүүсийг дуугүй өнгөрөхгүй, тусламж хүсэхэд нь уриалах нь аяны гол мессежүүдийн нэг юм.\nЖендэрт суурилсан хүчирхийлэл нь зөвхөн хохирогчийн асуудал биш, харин гэр бүл, нийгэм бүхэлдээ нөлөөлдөг ноцтой асуудал гэдгийг мэргэжилтнүүд онцолж байна. Хүчирхийллийн хэлбэр нь бие махбодын, сэтгэл зүйн, бэлгийн болон эдийн засгийн дарамт зэрэг олон янз байдаг бөгөөд олон тохиолдолд гэр бүлийн хүрээнд нуугдмал байдлаар үргэлжилдэг байна.\nАян арванхоёрдугаар сарын 10 буюу Хүний эрхийн өдөр хүртэл үргэлжилнэ. Энэ хугацаанд орон даяар сургалт, хэлэлцүүлэг, олон нийтийн арга хэмжээ зохион байгуулагдаж, хүчирхийллийг үл тэвчих, хохирогчдыг дэмжих уриалга дэвшүүлнэ.", "textEn": "The 16-day campaign against gender-based violence began on November 25 under the slogan 'Safe Everywhere'. The campaign is part of the annual global 16 Days of Activism against gender-based violence, aiming to prevent violence against women and children and to raise public awareness.\nAs part of the campaign, government bodies, civil society organisations and the media plan to work together to inform the public about the harm caused by violence, the support available to survivors and their legal protection. One of the campaign's central messages is to urge people who experience violence not to stay silent and to seek help.\nExperts stress that gender-based violence is not only the victim's problem but a serious issue affecting families and society as a whole. Violence takes many forms, including physical, psychological, sexual and economic abuse, and in many cases it continues hidden within the family.\nThe campaign will run until December 10, Human Rights Day. During this period, training sessions, discussions and public events will be held across the country, promoting zero tolerance for violence and support for survivors."},
  {"id": 6, "cat": "niigem", "time": "2 цаг", "timeEn": "2 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Rejected%20adoption%20application%20form%20with%20gavel%20placed%20on%20wooden%20background.%20-%2051070730302.jpg?width=760", "title": "АТГ: Хөрөнгө орлогын мэдүүлгийн хяналт шалгалтаар 12.1 тэрбум төгрөгийн зөрчлийг илрүүллээ", "titleEn": "Anti-Corruption Agency finds 12.1 billion tugrik in discrepancies in asset declarations", "text": "Авлигатай тэмцэх газраас хөрөнгө орлогын мэдүүлгийн хяналт шалгалтаар 12.1 тэрбум төгрөгийн зөрчлийг илрүүлсэн тухай арваннэгдүгээр сарын 25-нд мэдээллээ. Төрийн албан хаагчид жил бүр хөрөнгө, орлогоо мэдүүлэх үүрэгтэй бөгөөд уг мэдүүлгийг шалгах нь авлигаас урьдчилан сэргийлэх чухал хэрэгсэл юм.\nХөрөнгө орлогын мэдүүлгийн шалгалт нь мэдүүлсэн хөрөнгө, орлого нь бодит байдалтай нийцэж байгаа эсэх, хууль бусаар хөрөнгөжсөн байж болзошгүй тохиолдлыг илрүүлэхэд чиглэдэг. Илэрсэн зөрчлийн талаар хууль тогтоомжийн дагуу холбогдох арга хэмжээ авна гэж Авлигатай тэмцэх газраас мэдэгдлээ.\nЭнэ мэдээлэл нь хууль бус хөрөнгийг хураан авах тухай хуулийн төслийн талаарх хэлэлцүүлэг ид өрнөж буй үед гарч байна. Хууль зүйн сайд Г.Тэмүүлэн хуулийн төслийг Засгийн газрын хуралдаанаар хэлэлцүүлж, Улсын Их Хуралд өргөн мэдүүлэхээр төлөвлөж байгаа юм. Төсөл нь төрийн албан хаагчдын хууль бусаар олсон хөрөнгийг хураан авах эрх зүйн үндсийг бүрдүүлэх зорилготой.\nАвлигатай тэмцэх байгууллагуудын үйл ажиллагаа, ил тод байдал нь олон нийтийн анхаарлын төвд байдаг. Мэргэжилтнүүд хөрөнгө орлогын мэдүүлгийн шалгалтыг тогтмол, ил тод явуулах нь төрд итгэх итгэлийг бэхжүүлэхэд чухал гэж үзэж байна.", "textEn": "The Anti-Corruption Agency said on November 25 that checks of asset and income declarations had uncovered discrepancies worth 12.1 billion tugrik. Public officials are required to declare their assets and income each year, and verifying those declarations is an important tool in preventing corruption.\nThe checks aim to establish whether declared assets and income match reality and to detect possible cases of illicit enrichment. The agency said appropriate measures would be taken under the law regarding the discrepancies found.\nThe announcement comes as debate continues over a bill on confiscating unlawfully acquired assets. Justice Minister G. Temuulen plans to put the bill before the Cabinet and then submit it to parliament. The bill aims to create a legal basis for confiscating assets unlawfully obtained by public officials.\nThe work and transparency of anti-corruption bodies remain in the public spotlight. Experts say regular, transparent checks of asset declarations are important for strengthening trust in the state."},
  {"id": 7, "cat": "edzasag", "time": "2 цаг", "timeEn": "2 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Tavan%20Tolgoi%2005.jpg?width=760", "title": "“Эрдэнэс Тавантолгой” ХК Чингис хаан үндэсний баялгийн санд 675.7 тэрбум төгрөг төвлөрүүллээ", "titleEn": "'Erdenes Tavan Tolgoi' channels 675.7 billion tugrik into Chinggis Khaan National Wealth Fund", "text": "“Эрдэнэс Тавантолгой” ХК Чингис хаан үндэсний баялгийн санд 675.7 тэрбум төгрөг төвлөрүүлсэн тухай арваннэгдүгээр сарын 25-нд мэдээллээ. Тавантолгойн орд нь Монголын нүүрсний экспортын гол эх үүсвэр бөгөөд тус компанийн орлогоос бүрдсэн хөрөнгийг баялгийн санд төвлөрүүлж байгаа нь тус сангийн хөрөнгийг нэмэгдүүлэхэд чухал хувь нэмэр болж байна.\nЧингис хаан үндэсний баялгийн сан нь байгалийн баялгийн орлогыг хуримтлуулж, ирээдүй хойч үедээ өвлүүлэх, эдийн засгийн тогтвортой байдлыг хангах зорилготойгоор байгуулагдсан юм. Санд төвлөрсөн хөрөнгийг хуульд заасан зориулалтаар зарцуулж, улс орны хөгжлийн томоохон төслүүдийг санхүүжүүлэхэд ашигладаг.\nНүүрсний салбар нь Монголын эдийн засгийн гол тулгууруудын нэг бөгөөд экспортын орлогын дийлэнх хувийг бүрдүүлдэг. Нүүрсний экспорт энэ оны төгсгөлд 100 сая тоннд хүрэх төлөвтэй байгаа нь салбарын орлого, улмаар баялгийн санд орох хөрөнгийн хэмжээг нэмэгдүүлэх хүчин зүйл болж байна.\nБаялгийн сангийн хөрөнгийг ил тод, үр ашигтай зарцуулах асуудал олон нийтийн анхаарлын төвд байдаг. Мэргэжилтнүүд сангийн хөрөнгийн зарцуулалтыг хянах, тайлагнах механизмыг бэхжүүлэх нь иргэдийн итгэлийг нэмэгдүүлэхэд чухал гэж үзэж байна.", "textEn": "Erdenes Tavan Tolgoi JSC said on November 25 that it has channelled 675.7 billion tugrik into the Chinggis Khaan National Wealth Fund. The Tavan Tolgoi deposit is the main source of Mongolia's coal exports, and channelling revenue from the company into the wealth fund is an important contribution to growing the fund.\nThe Chinggis Khaan National Wealth Fund was established to accumulate income from natural resources, preserve it for future generations and support economic stability. The funds accumulated in it are spent for purposes set out in law and used to finance major national development projects.\nThe coal sector is one of the pillars of Mongolia's economy and accounts for the largest share of export earnings. Coal exports are expected to reach 100 million tonnes by the end of this year, which will increase sector revenues and the amount flowing into the wealth fund.\nThe transparent and efficient use of the wealth fund's resources remains in the public spotlight. Experts say strengthening the mechanisms for monitoring and reporting on the fund's spending is important for building public trust."},
  {"id": 8, "cat": "edzasag", "time": "3 цаг", "timeEn": "3 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Asian%20Development%20Bank%20headquarters.jpg?width=760", "title": "АХБ-тай санхүүжилтийн ерөнхий хөтөлбөрийг соёрхон батлах хуулийн төслийг УИХ-д өргөн мэдүүлэв", "titleEn": "Bill to ratify ADB financing framework submitted to parliament", "text": "Монгол Улс болон Азийн хөгжлийн банк хоорондын “Санхүүжилтийн ерөнхий хөтөлбөр”-ийг соёрхон батлах тухай хуулийн төслийг Улсын Их Хуралд өргөн мэдүүлэв. Аравдугаар сард гарын үсэг зурсан уг гэрээ нь Монголд Азийн хөгжлийн банкнаас олгох санхүүжилтийн эрх зүйн үндсийг бүрдүүлэх юм.\nСангийн сайд Улсын Их Хурлын гишүүдэд мэдээлэхдээ, Азийн хөгжлийн банкнаас олгох төсвийн дэмжлэгийн зээлийг яриа хэлэлцээний явцад 200 сая ам.доллар болгон нэмэгдүүлсэн тухай дурджээ. Түүнчлэн гамшгийн үед ашиглах 250 сая ам.долларын тусдаа зээлийн шугамыг тохиролцсон байна.\nАзийн хөгжлийн банк нь Монголын дэд бүтэц, эрчим хүч, боловсрол, эрүүл мэнд зэрэг салбарт хэрэгжиж буй олон төслийг санхүүжүүлж ирсэн түүхтэй. Санхүүжилтийн ерөнхий хөтөлбөр нь тус банкнаас олгох зээл, тусламжийг зохицуулах нэгдсэн хүрээ болж, хамтын ажиллагааг илүү тогтвортой, урьдчилан таамаглах боломжтой болгох зорилготой.\nХуулийн төслийг Улсын Их Хурал хэлэлцэн баталбал, Монгол Улс Азийн хөгжлийн банкнаас олгох санхүүжилтийг төсвийн дэмжлэг, гамшгийн эрсдэлийг бууруулах зэрэг чиглэлээр ашиглах боломжтой болно. Энэ нь эдийн засгийн тогтвортой байдал, гамшигт тэсвэртэй байдлыг бэхжүүлэхэд чухал ач холбогдолтой гэж Засгийн газар үзэж байна.", "textEn": "A bill to ratify the 'Framework Financing Programme' between Mongolia and the Asian Development Bank has been submitted to parliament. The agreement, signed in October, creates the legal basis for financing from the Asian Development Bank to Mongolia.\nThe finance minister told lawmakers that the budget-support loan from the Asian Development Bank was raised to 200 million US dollars during negotiations. A separate 250 million dollar credit line for use in disasters was also agreed.\nThe Asian Development Bank has a long history of financing projects in Mongolia in infrastructure, energy, education and health. The framework financing programme provides a single framework governing the bank's loans and assistance, aiming to make cooperation more stable and predictable.\nIf parliament approves the bill, Mongolia will be able to use the bank's financing for budget support and for reducing disaster risk. The government says this is important for strengthening economic stability and resilience to disasters."},
  {"id": 9, "cat": "edzasag", "time": "3 цаг", "timeEn": "3 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/TurowCoalMine.jpg?width=760", "title": "Нүүрсний экспорт оны төгсгөлд 100 сая тоннд хүрэх төлөвтэй", "titleEn": "Coal exports on track to reach 100 million tonnes by year end", "text": "Монголын нүүрсний экспорт энэ оны төгсгөлд 100 сая тоннд хүрэх төлөвтэй байгаа тухай арваннэгдүгээр сарын 25-нд мэдээллээ. Нүүрс нь Монголын экспортын хамгийн чухал бүтээгдэхүүн бөгөөд экспортын орлогын дийлэнх хувийг бүрдүүлдэг. Экспортын хэмжээ өсөх нь улсын төсөв, валютын нөөц, эдийн засгийн өсөлтөд шууд эерэг нөлөө үзүүлдэг.\nСүүлийн жилүүдэд нүүрсний экспортыг нэмэгдүүлэхэд хилийн боомтуудын нэвтрүүлэх чадварыг сайжруулах, төмөр замын холболтыг өргөтгөх, гаалийн бүрдүүлэлтийг хөнгөвчлөх зэрэг арга хэмжээ чухал үүрэг гүйцэтгэж байна. Тавантолгой-Гашуунсухайт, Тавантолгой-Зүүнбаян чиглэлийн төмөр зам ашиглалтад орсноор нүүрс тээвэрлэх хүчин чадал нэмэгдсэн юм.\nНүүрсний үнэ дэлхийн зах зээл дээрх эрэлт, нийлүүлэлтээс хамаарч хэлбэлздэг тул экспортын орлого ч үүнийг дагаж өөрчлөгддөг. Тиймээс Засгийн газар нүүрсний экспортын хэмжээг нэмэгдүүлэхийн зэрэгцээ боловсруулах үйлдвэрлэл, нэмүү өртөг шингэсэн бүтээгдэхүүний үйлдвэрлэлийг хөгжүүлэхэд анхаарч байна.\nЭкспортын өсөлт нь “Эрдэнэс Тавантолгой” зэрэг төрийн өмчит компаниудын орлого, Чингис хаан үндэсний баялгийн санд төвлөрөх хөрөнгийн хэмжээг нэмэгдүүлж байна. Мэргэжилтнүүд нүүрсний экспортоос хараат байдлыг бууруулж, эдийн засгийг төрөлжүүлэх нь урт хугацааны зорилт хэвээр байна гэж онцолж байна.", "textEn": "Mongolia's coal exports are on track to reach 100 million tonnes by the end of this year, it was reported on November 25. Coal is Mongolia's most important export product, accounting for the largest share of export earnings. Growth in export volumes has a direct positive effect on the state budget, foreign exchange reserves and economic growth.\nIn recent years, improving the capacity of border ports, expanding rail connections and simplifying customs clearance have played a key role in increasing coal exports. The Tavan Tolgoi-Gashuunsukhait and Tavan Tolgoi-Zuunbayan railways entering service have increased coal transport capacity.\nCoal prices fluctuate with global supply and demand, and export earnings move with them. The government is therefore focusing not only on increasing export volumes but also on developing processing industries and value-added production.\nExport growth is raising the revenues of state-owned companies such as Erdenes Tavan Tolgoi and the amount flowing into the Chinggis Khaan National Wealth Fund. Experts stress that reducing dependence on coal exports and diversifying the economy remains a long-term goal."},
  {"id": 10, "cat": "delhii", "time": "4 цаг", "timeEn": "4 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/August%202013%20IMG%203371%20Honiara%2C%20Solomon%20Islands.%20%289574489176%29.jpg?width=760", "title": "Австрали, Соломоны арлууд аюулгүй байдлын түншлэлийн гэрээ байгуулав", "titleEn": "Australia, Solomon Islands sign landmark security partnership", "text": "Австрали, Соломоны арлууд аюулгүй байдлын түншлэлийн түүхэн гэрээ байгуулсан тухай арваннэгдүгээр сарын 26-нд мэдээллээ. Энэхүү гэрээ нь Номхон далайн бүс нутгийн аюулгүй байдлын хамтын ажиллагааг бэхжүүлэхэд чиглэж байгаа бөгөөд ажиглагчид үүнийг Хятадын бүс нутаг дахь нөлөөг сааруулах зорилготой алхам гэж үзэж байна.\nСоломоны арлууд нь Номхон далайн өмнөд хэсэгт орших арлын улс бөгөөд сүүлийн жилүүдэд Хятадтай ойртон, аюулгүй байдлын салбарт хамтран ажиллах гэрээ байгуулсан нь Австрали болон түүний холбоотнуудын санааг зовоож байсан юм. Шинэ гэрээ нь Австрали, Соломоны арлуудын хоорондын уламжлалт түншлэлийг сэргээж, бэхжүүлэхэд чиглэж байна.\nГэрээний хүрээнд талууд батлан хамгаалах, цагдаа, онцгой байдлын салбарт хамтран ажиллах, мэдээлэл солилцох, хамтарсан сургуулилт хийхээр төлөвлөж байна. Энэ нь Номхон далайн арлын орнуудын аюулгүй байдал, тогтвортой байдлыг хангахад чиглэсэн бүс нутгийн хүчин чармайлтын нэг хэсэг юм.\nНомхон далайн бүс нутагт их гүрнүүдийн өрсөлдөөн эрчимжиж байгаа үед энэхүү гэрээ нь бүс нутгийн геополитикийн тэнцвэрт нөлөөлөх үйл явдал гэж шинжээчид үзэж байна. Австрали нь Номхон далайн арлын орнуудын аюулгүй байдлын гол түнш хэвээр байх бодлогоо баримталж байна.", "textEn": "Australia and the Solomon Islands have signed a landmark security partnership, it was reported on November 26. The agreement aims to strengthen security cooperation in the Pacific region, and observers see it as a move to counter China's influence in the region.\nThe Solomon Islands, a Pacific island nation, has grown closer to China in recent years and signed a security cooperation agreement with Beijing, which concerned Australia and its allies. The new agreement aims to restore and strengthen the traditional partnership between Australia and the Solomon Islands.\nUnder the agreement, the two sides plan to cooperate in defence, policing and emergency response, share information and hold joint exercises. It is part of regional efforts to ensure the security and stability of Pacific island nations.\nAnalysts say the agreement will affect the geopolitical balance in the Pacific at a time of intensifying great-power competition in the region. Australia maintains its policy of remaining the main security partner of Pacific island nations."},
  {"id": 11, "cat": "delhii", "time": "4 цаг", "timeEn": "4 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Tiangong%20space%20station%20as%20seen%20from%20M.B%20Gonnet%20in%20March%202024%20-%20BugWarp.jpg?width=760", "title": "Пакистаны анхны сансрын нисгэгч Хятадын Тяньгун станцад хүрлээ", "titleEn": "Pakistan's first astronaut reaches China's Tiangong station", "text": "Пакистаны анхны сансрын нисгэгч Мухаммад Зеешан Али Хятадын Тяньгун сансрын станцад хүрч, Хятадын сансрын станцад очсон анхны гадаад сансрын нисгэгч боллоо. Тэрбээр Шэньжоу-24 хөлгөөр станцад хүрсэн бөгөөд энэ нь Хятад, Пакистаны сансрын салбарын хамтын ажиллагааны түүхэн үйл явдал болж байна.\nТяньгун станц нь Хятадын бие даан барьсан сансрын станц бөгөөд дэлхийн тойрог замд ажиллаж байгаа юм. Хятад улс сүүлийн жилүүдэд сансрын хөтөлбөрөө эрчимтэй хөгжүүлж, саран дээрх судалгаа, сансрын станцын ажиллагаа зэрэг олон чиглэлээр амжилт гаргаж байна. Гадаад улсын сансрын нисгэгчийг станцад хүлээн авсан нь Хятадын сансрын хөтөлбөрийн олон улсын хамтын ажиллагааг өргөжүүлж буйгийн илрэл юм.\nПакистаны хувьд анхны иргэнээ сансарт илгээсэн нь тус улсын шинжлэх ухаан, технологийн хөгжлийн томоохон алхам болж байна. Хоёр улс нь эдийн засаг, дэд бүтэц, батлан хамгаалах зэрэг олон салбарт нягт хамтран ажилладаг бөгөөд сансрын салбарын хамтын ажиллагаа нь тэдний стратегийн түншлэлийг улам бэхжүүлж байна.\nСансрын нисгэгч станцад байх хугацаандаа шинжлэх ухааны туршилт хийж, судалгааны ажилд оролцох юм. Энэхүү нислэг нь хөгжиж буй орнуудын сансрын судалгаанд оролцох боломжийг өргөжүүлж, олон улсын сансрын хамтын ажиллагааны шинэ хуудас нээж байна гэж ажиглагчид үзэж байна.", "textEn": "Pakistan's first astronaut, Muhammad Zeeshan Ali, has reached China's Tiangong space station, becoming the first foreign astronaut to visit the Chinese station. He arrived aboard the Shenzhou-24 spacecraft in what is a historic moment for space cooperation between China and Pakistan.\nTiangong is China's independently built space station, operating in Earth orbit. China has rapidly developed its space programme in recent years, achieving success in lunar exploration, station operations and many other areas. Welcoming a foreign astronaut to the station shows the expansion of international cooperation in China's space programme.\nFor Pakistan, sending its first citizen into space is a major step in the country's scientific and technological development. The two countries cooperate closely in many areas, including the economy, infrastructure and defence, and space cooperation further strengthens their strategic partnership.\nDuring his stay, the astronaut will conduct scientific experiments and take part in research work. Observers say the flight expands opportunities for developing countries to take part in space research and opens a new chapter in international space cooperation."},
  {"id": 12, "cat": "delhii", "time": "5 цаг", "timeEn": "5 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Buildings%20in%20Cartagena%2C%20Colombia%2001.jpg?width=760", "title": "Колумбын цагдаа нар супермаркетад барьцаалагдсан хүмүүсийг суллав", "titleEn": "Colombian forces storm supermarket and free hostages", "text": "Колумбын цагдаагийн тусгай хүчин Картахена хотын супермаркетэд зэвсэгт этгээдүүдэд барьцаалагдсан хүмүүсийг сулласан тухай арваннэгдүгээр сарын 26-нд мэдээллээ. Зэвсэгт этгээдүүд супермаркетэд нэвтэрч, олон арван хүнийг барьцаалсан бөгөөд цагдаа нар дэлгүүрийг бүсэлж, хэлэлцээ хийсний дараа дайрч, барьцааны хүмүүсийг аварчээ.\nЭнэ явдал нь Колумбын хотуудад гэмт хэрэг, хүчирхийлэлтэй тэмцэх асуудлыг дахин олны анхааралд орууллаа. Тус улсын эрх баригчид зэвсэгт бүлэглэл, зохион байгуулалттай гэмт хэрэгтэй тэмцэх ажиллагааг эрчимжүүлж байгаа бөгөөд иргэдийн аюулгүй байдлыг хангах нь Засгийн газрын тэргүүлэх зорилтуудын нэг юм.\nҮүний зэрэгцээ Колумб улс түүхэн энхийн гэрээний 10 жилийн ойг тэмдэглэж байна. Арван жилийн өмнө Засгийн газар болон зэвсэгт босогчдын хооронд байгуулсан энхийн гэрээ нь олон арван жил үргэлжилсэн дотоодын мөргөлдөөнийг зогсоох зорилготой байсан юм. Гэвч гэрээний зарим үүрэг амлалт бүрэн хэрэгжээгүй байгаа талаар НҮБ анхааруулж байна.\nШинжээчдийн үзэж буйгаар, энхийн гэрээний ойг тэмдэглэж буй энэ үед барьцааны хэрэг гарсан нь тус улсад аюулгүй байдал, энх тайвныг бэхжүүлэхэд тулгарч буй сорилтуудыг харуулж байна. Эрх баригчид гэмт хэрэгтэй тэмцэх, энхийн гэрээг бүрэн хэрэгжүүлэх чиглэлээр хүчин чармайлтаа үргэлжлүүлэхээ амлаж байна.", "textEn": "Colombian special police forces freed hostages held by armed men at a supermarket in the city of Cartagena, it was reported on November 26. The gunmen entered the supermarket and took dozens of people hostage; police surrounded the store, negotiated, and then stormed it to rescue the hostages.\nThe incident has again drawn public attention to the fight against crime and violence in Colombian cities. The authorities have stepped up operations against armed groups and organised crime, and ensuring public safety is one of the government's priorities.\nAt the same time, Colombia is marking the tenth anniversary of its historic peace agreement. Signed ten years ago between the government and armed rebels, the agreement aimed to end decades of internal conflict. The United Nations has warned, however, that some of the agreement's commitments remain unfulfilled.\nAnalysts say the hostage incident, occurring as the peace anniversary is marked, shows the challenges facing efforts to strengthen security and peace in the country. The authorities have pledged to continue fighting crime and fully implementing the peace agreement."},
  {"id": 13, "cat": "delhii", "time": "5 цаг", "timeEn": "5 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Garment%20workers%20queuing%20for%20subsidized%20rice%20at%20an%20Open%20Market%20Sale%20outlet%20in%20Mirpur-7%2C%20Dhaka%2C%202026-11-13.jpg?width=760", "title": "Бангладешийн оёдлын ажилчдын цалин 36 хувиар нэмэгдлээ", "titleEn": "Bangladesh garment workers win 36% wage hike", "text": "Бангладешийн оёдлын ажилчдын цалин 36 хувиар нэмэгдсэн тухай арваннэгдүгээр сарын 26-нд мэдээллээ. Анхан шатны оёдлын ажилчдын сарын доод цалин ингэж нэмэгдэж байгаа нь тус улсын сая сая ажилчин, тэдний гэр бүлийн амьжиргаанд шууд нөлөөлөх шийдвэр болж байна.\nОёдлын салбар нь Бангладешийн эдийн засгийн гол тулгуур бөгөөд тус улсын экспортын дийлэнх хувийг бүрдүүлдэг. Дэлхийн томоохон хувцасны брэндүүдэд зориулан хувцас үйлдвэрлэдэг тус салбарт олон сая хүн ажилладаг бөгөөд дийлэнх нь эмэгтэйчүүд юм. Цалингийн нэмэгдэл нь ажилчдын амьжиргааны түвшинг дээшлүүлэх, инфляцын дарамтыг бууруулахад чиглэж байна.\nОёдлын ажилчид сүүлийн жилүүдэд цалингаа нэмэгдүүлэхийг шаардан жагсаж, ажил хаялт зохион байгуулж ирсэн юм. Эрх баригчид, үйлдвэрлэгчид, ажилчдын төлөөлөл хоорондын хэлэлцээний үр дүнд энэхүү тохиролцоонд хүрсэн байна. Тохиролцоо нь салбарын тогтвортой байдлыг хангаж, үйлдвэрлэлийн тасралтгүй ажиллагааг дэмжих зорилготой.\nШинжээчдийн үзэж буйгаар, цалингийн нэмэгдэл нь ажилчдын амьжиргааг сайжруулахын зэрэгцээ үйлдвэрлэгчдийн зардлыг нэмэгдүүлж, олон улсын өрсөлдөөнд нөлөөлж болзошгүй. Гэвч шударга цалин, хөдөлмөрийн нөхцөл нь салбарын урт хугацааны тогтвортой хөгжлийн үндэс гэж тэд онцолж байна.", "textEn": "Bangladesh's garment workers have won a 36 percent wage increase, it was reported on November 26. The rise in the minimum monthly wage for entry-level garment workers will directly affect the livelihoods of millions of workers and their families.\nThe garment sector is the backbone of Bangladesh's economy, accounting for the largest share of the country's exports. Millions of people, most of them women, work in the sector producing clothing for major global brands. The wage increase aims to raise workers' living standards and ease the pressure of inflation.\nGarment workers have staged protests and strikes in recent years demanding higher pay. The agreement was reached through negotiations between the authorities, manufacturers and workers' representatives. It aims to ensure stability in the sector and support uninterrupted production.\nAnalysts say the wage rise will improve workers' livelihoods while also raising manufacturers' costs and potentially affecting international competitiveness. But they stress that fair pay and working conditions are the foundation of the sector's long-term sustainable development."},
  {"id": 14, "cat": "delhii", "time": "6 цаг", "timeEn": "6 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Pyongyang%20Railway%20Station%20platform%2C%20Pyongyang%2C%20North%20Korea%20%28DPRK%29.jpg?width=760", "title": "Хойд Солонгос Швейцарын дипломат төлөөлөгчийн газрыг хаахыг тушаав", "titleEn": "North Korea orders Switzerland to close its diplomatic office", "text": "Хойд Солонгос Пхеньян дахь Швейцарын дипломат төлөөлөгчийн газрын тэргүүнийг хөөж, төлөөлөгчийн газрыг хаахыг тушаасан тухай арваннэгдүгээр сарын 26-нд мэдээллээ. Швейцарын тал саяхан Пхеньянд дипломат төлөөлөгчийн газраа нээсэн бөгөөд уг шийдвэр нь олон улсын хориг арга хэмжээтэй холбоотой гэж үзэж байна.\nШвейцар улс нь Хойд Солонгостой харилцахдаа зуучлагчийн үүрэг гүйцэтгэж ирсэн түүхтэй. Тус улс нь Солонгосын хойг дахь харилцаа холбоог хадгалах, хүмүүнлэгийн тусламж үзүүлэх зэрэг чиглэлээр ажилладаг бөгөөд Пхеньянд төлөөлөгчийн газраа нээсэн нь харилцааг өргөжүүлэх алхам гэж үзэж байсан юм.\nХойд Солонгосын зүгээс гаргасан энэхүү шийдвэр нь тус улсын гадаад харилцаа, хориг арга хэмжээний дэглэмтэй холбоотой хурцадмал байдлыг харуулж байна. Хойд Солонгосын цөмийн болон пуужингийн хөтөлбөрийн улмаас НҮБ-ын Аюулгүйн зөвлөлөөс тус улсад хориг арга хэмжээ ногдуулсан бөгөөд тус улс эдгээр хоригийг эсэргүүцэж ирсэн юм.\nШвейцарын Гадаад хэргийн яам шийдвэрийн талаар мэдэгдэл хийхээр төлөвлөж байгаа бөгөөд Пхеньянд ажиллаж байсан дипломат ажилтнуудын аюулгүй байдлыг хангах асуудлыг хэлэлцэж байна. Ажиглагчид энэ үйл явдал нь Солонгосын хойгийн дипломат харилцаанд сөрөг нөлөө үзүүлж болзошгүй гэж үзэж байна.", "textEn": "North Korea has expelled the head of Switzerland's diplomatic office in Pyongyang and ordered the office to close, it was reported on November 26. Switzerland had recently opened its diplomatic office in Pyongyang, and the decision is seen as linked to international sanctions.\nSwitzerland has a history of acting as an intermediary in relations with North Korea. The country works to maintain communication on the Korean Peninsula and provide humanitarian aid, and opening an office in Pyongyang was seen as a step towards expanding relations.\nNorth Korea's decision reflects tensions over its foreign relations and the sanctions regime. The UN Security Council has imposed sanctions on North Korea over its nuclear and missile programmes, which Pyongyang has long opposed.\nThe Swiss foreign ministry is expected to issue a statement on the decision, and the safety of diplomatic staff who worked in Pyongyang is being discussed. Observers say the move could harm diplomatic engagement on the Korean Peninsula."},
  {"id": 15, "cat": "sport", "time": "6 цаг", "timeEn": "6 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/3x3%20basketball%20competition%20in%20mongolia%2818%29.jpg?width=760", "title": "FIBA Азийн цом-2029: өнөөдөр Монгол, Индонезийн шигшээ багууд тоглоно", "titleEn": "FIBA Asia Cup 2029 qualifiers: Mongolia face Indonesia tonight", "text": "Сагсан бөмбөгийн 2029 оны Азийн аварга шалгаруулах тэмцээний урьдчилсан шатны хоёрдугаар тойргийн тоглолт Улаанбаатар хотын “М Банк Арена”-д өнөөдрөөс эхэлж байна. Монголын шигшээ баг өнөөдөр 19:00 цагт Индонезийн багтай тоглох бөгөөд маргааш Хонконг, арваннэгдүгээр сарын 29-нд Малайзын багтай учраа таарна.\nМонголын сагсан бөмбөгийн холбооноос шигшээ багийн 12 тоглогчийн нэрийг зарласан бөгөөд багийн ахлагчаар АНУ-ын Хөгжлийн лигийн “Осеола Мэжик” багийн тоглогч Ш.Энхийн-Одыг сонгожээ. Шигшээд Ш.Энхийн-Од, А.Азбаяр, Х.Оргил, Ч.Маргад, Б.Барсболд, Э.Түшиг, С.Биндэръяа, Г.Дөлгөөн, Н.Батбаяр, М.Өлзий-Орших, Г.Болор-Эрдэнэ, О.Өсөхбаяр нар багтсан бөгөөд багийн ахлах дасгалжуулагчаар Э.Ариунболд ажиллана.\nМанай шигшээ баг “F” хэсэгт Тайланд, Хонконг, Малайз, Индонез, Фижи багуудтай орсон бөгөөд өмнөх шатны гурван тоглолтоос хоёр хожил авч, 5 оноотой хэсгийнхээ гуравдугаар байрт бичигдэж байна. Хэсгээс шалгарсан эхний дөрвөн баг 2029 оны Азийн цомын урьдчилсан шатны үндсэн тэмцээнд оролцох эрхээ авна.\nГадаадын лигт тоглож байсан дөрвөн тоглогчоос гурав нь эх орондоо ирсэн бол Японы “Фүкүй Блоувайндс” багт зүтгэж буй Х.Оргил өнөөдөр ирж, багтайгаа нэгдэнэ. Шигшээ багийн тоглолтуудыг олон мянган хөгжөөн дэмжигч “М Банк Арена”-д очиж үзэх боломжтой бөгөөд Монголын хөгжөөн дэмжигчид шигшээ багаасаа ялалт хүлээж байна.", "textEn": "The second-round qualifiers for the FIBA Asia Cup 2029 begin today at the M Bank Arena in Ulaanbaatar. Mongolia's national team will play Indonesia tonight at 19:00, followed by Hong Kong tomorrow and Malaysia on November 29.\nThe Mongolian Basketball Association has named the 12-player squad, with Sh. Enkhjin-Od, who plays for the Osceola Magic in the NBA G League, appointed captain. The squad includes Sh. Enkhjin-Od, A. Azbayar, Kh. Orgil, Ch. Margad, B. Barsbold, E. Tushig, S. Binderiya, G. Dulguun, N. Batbayar, M. Ulzii-Orshikh, G. Bolor-Erdene and O. Usukhbayar, with E. Ariunbold as head coach.\nMongolia are in Group F with Thailand, Hong Kong, Malaysia, Indonesia and Fiji, and currently sit third in the group with two wins from three games and five points. The top four teams from the group will qualify for the main qualifying tournament for the 2029 Asia Cup.\nThree of the four players based in foreign leagues have returned home, while Kh. Orgil, who plays for Fukui Blowinds in Japan, arrives today to join the squad. Thousands of fans will be able to watch the games at the M Bank Arena, and Mongolian supporters will be expecting victory from the national team."},
  {"id": 16, "cat": "sport", "time": "7 цаг", "timeEn": "7 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Esports%20at%20movistar%20arena%20buenosaires.jpg?width=760", "title": "PGL Major: Chinggis Warriors GOSH-ийг хожиж, тэмцээнээ үргэлжлүүлж байна", "titleEn": "PGL Major: Chinggis Warriors beat GOSH to stay alive", "text": "Монголын Chinggis Warriors баг Сингапурт болж буй Counter-Strike 2 тоглоомын дэлхийн аварга шалгаруулах PGL Major Singapore 2026 тэмцээний шийдвэрлэх тоглолтод GOSH багийг 2:1-ээр хожиж, тэмцээнээ үргэлжлүүлж байна. Тоглолт арваннэгдүгээр сарын 25-нд болж, манай баг Ancient мапад 13:11, шийдвэрлэх Nuke мапад 13:10-оор ялсан бол Dust2 мапад 6:13-аар ялагдсан юм.\nGOSH багийн бүрэлдэхүүнд дэлхийн шилдэг тоглогчдын нэг Александр “s1mple” Костылев болон Монголын Senzu, mzinho нар тоглож байсан бөгөөд тэдний хувьд энэхүү ялагдал нь тэмцээнээс хасагдах шалтгаан боллоо. GOSH баг тэмцээнд гурван тоглолтод дараалан ялагдаж, 0:3 гэсэн амжилттайгаар Мажороос хасагдсан анхны багуудын нэг болов. S1mple-ийн хувьд энэ нь түүний карьерын хамгийн хүнд тэмцээнүүдийн нэг болсон гэж шинжээчид үзэж байна.\nChinggis Warriors баг одоо 1:2 гэсэн амжилттай байгаа бөгөөд өнөөдөр буюу арваннэгдүгээр сарын 26-нд Wildcard багтай шийдвэрлэх тоглолт хийнэ. Энэ тоглолтод ялагдсан баг тэмцээнээ өндөрлүүлэх бол ялсан баг нь хоёрдугаар шатанд шалгарах эрхийн төлөө өрсөлдөхөө үргэлжлүүлнэ.\nТэмцээнд Монгол Улсаас хоёр баг оролцож байгаа бөгөөд Азийн бүсийн чансааны нэгдүгээрт бичигдэж буй The MongolZ баг хоёрдугаар шатнаас тэмцээнээ эхлүүлэх юм. GOSH-д тоглож буй Senzu, mzinho нарыг оролцуулбал нийт 12 Монгол тамирчин дэлхийн шилдгүүдтэй өрсөлдөж байна. Тэмцээний шагналын сан 1.25 сая ам.доллар бөгөөд ялагч баг 500 мянган ам.доллар хүртэнэ.", "textEn": "Mongolia's Chinggis Warriors beat GOSH 2-1 in a decisive match at the PGL Major Singapore 2026 Counter-Strike 2 world championship in Singapore, keeping their tournament alive. Played on November 25, the Mongolian side won Ancient 13-11 and the deciding Nuke map 13-10, losing Dust2 6-13.\nGOSH fielded one of the world's best players, Oleksandr 's1mple' Kostyliev, alongside Mongolians Senzu and mzinho, and the defeat eliminated them from the tournament. GOSH lost all three of their matches, finishing 0-3 as one of the first teams knocked out of the Major. Analysts say it was one of the toughest tournaments of s1mple's career.\nChinggis Warriors now stand at 1-2 and will play a decisive match against Wildcard today, November 26. The loser will go home, while the winner will continue fighting for a place in Stage 2.\nTwo Mongolian teams are competing in the tournament, and The MongolZ, ranked first in Asia, will begin their campaign in Stage 2. Including Senzu and mzinho at GOSH, a total of 12 Mongolian players are competing against the world's best. The tournament's prize pool is 1.25 million US dollars, with the winner taking 500,000 dollars."},
  {"id": 17, "cat": "soyl", "time": "7 цаг", "timeEn": "7 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Chinggis%20Khaan%20National%20Museum%2001.jpg?width=760", "title": "“Тусгаар тогтнол” дүрслэх урлагийн үзэсгэлэн өнөөдөр нээлтээ хийнэ", "titleEn": "'Independence' fine art exhibition opens today", "text": "Монгол Улсын Ерөнхийлөгчийн ивээл дор зохион байгуулдаг “Тусгаар тогтнол” дүрслэх урлагийн үзэсгэлэнгийн нээлт өнөөдөр буюу арваннэгдүгээр сарын 26-нд Монголын Урчуудын Эвлэлийн арт галерейд болно. Үзэсгэлэн нь Улс тунхагласны 102 жилийн ойд зориулагдсан бөгөөд Монголын уран бүтээлчдийн эх орон, тусгаар тогтнол, үндэсний бахархлын сэдэвт бүтээлүүдийг олон нийтэд толилуулна.\nДүрслэх урлагийн үзэсгэлэн нь Монголын соёлын амьдралын чухал хэсэг бөгөөд уран бүтээлчид өөрсдийн бүтээлээр дамжуулан эх орныхоо түүх, соёл, байгаль, ард түмний амьдралыг илэрхийлдэг уламжлалтай. “Тусгаар тогтнол” үзэсгэлэн жил бүр зохион байгуулагдаж, шилдэг уран бүтээлчдийн бүтээлийг шалгаруулдаг юм.\nОйн өдрийг тохиолдуулан өнөөдөр соёлын бусад арга хэмжээ ч зохион байгуулагдана. Чойжин ламын сүм музейд “Дуут өргөө” гэр тоглолт болох бөгөөд Улсын драмын эрдмийн театрын тайзнаа “Тэнгэрийн хүү” жүжиг толилуулагдана. Эдгээр арга хэмжээ нь баярын өдрийн соёлын хөтөлбөрийг баяжуулж байна.\nУлс орон даяар арваннэгдүгээр сарын турш “Соёлын бүтээлч сар-2026” сарын аян “Монгол бахархал” уриан дор зохион байгуулагдаж байгаа бөгөөд энэ долоо хоног “Түүхэн хүмүүн”-д зориулагдсан юм. Аймаг, сум бүрд түүхэн хүмүүс, уран бүтээлчдийн өв уламжлалыг онцолсон арга хэмжээ өрнөж байна.", "textEn": "The 'Independence' fine art exhibition, held under the auspices of the President of Mongolia, opens today, November 26, at the art gallery of the Mongolian Artists' Union. Dedicated to the 102nd anniversary of the proclamation of the Republic, the exhibition presents works by Mongolian artists on the themes of homeland, independence and national pride.\nFine art exhibitions are an important part of Mongolia's cultural life, and artists traditionally express their country's history, culture, nature and people's lives through their work. The 'Independence' exhibition is held every year, showcasing the work of leading artists.\nOther cultural events will also take place today to mark the anniversary. A 'Duut Urguu' ger concert will be held at the Choijin Lama Temple Museum, and the play 'Son of Heaven' will be staged at the State Academic Drama Theatre. These events enrich the holiday's cultural programme.\nThroughout November, the 'Creative Culture Month 2026' campaign is being held nationwide under the slogan 'Mongol Pride', with this week dedicated to 'Historical Figures'. Events highlighting the legacy of historic people and artists are taking place in every province and district."},
  {"id": 18, "cat": "tech", "time": "8 цаг", "timeEn": "8 hours", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Artificial%20Intelligence%20%28AI%29%20and%20Robotics%20exhibition%20at%20the%20Heinz%20Nixdorf%20MuseumsForum.jpg?width=760", "title": "АНУ-ын мужууд Grok чатботын бүтээсэн бэлгийн шинжтэй зургуудын улмаас Маскийн компаниудыг шүүхэд өгчээ", "titleEn": "US states sue Musk companies over sexualised images made by Grok chatbot", "text": "Америкийн Нэгдсэн Улсын хэд хэдэн муж Илон Маскийн компаниудыг хиймэл оюун ухааны Grok чатботын бүтээсэн бэлгийн шинжтэй зургууд олноор тархсантай холбогдуулан шүүхэд өгсөн тухай арваннэгдүгээр сарын 26-нд мэдээллээ. Мужийн эрх баригчдын үзэж буйгаар, чатбот нь хүмүүсийн зөвшөөрөлгүйгээр бэлгийн шинжтэй дүрслэл бүтээж, тархаах боломжийг олгосон нь хууль зөрчсөн үйлдэл юм.\nЭнэ хэрэг нь хиймэл оюун ухааны технологийг зүй бусаар ашиглах, ялангуяа хүмүүсийн дүр төрхийг зөвшөөрөлгүйгээр өөрчлөн бэлгийн шинжтэй агуулга бүтээх асуудлыг олны анхааралд орууллаа. Ийм төрлийн агуулга нь хохирогчдын нэр хүнд, сэтгэл зүйд ноцтой хохирол учруулж, цахим орчин дахь хүчирхийллийн шинэ хэлбэр болж байна гэж мэргэжилтнүүд анхааруулж байна.\nТехнологийн компаниуд хиймэл оюун ухааны хэрэгслээ зүй бусаар ашиглахаас сэргийлэх үүрэгтэй бөгөөд хэрэглэгчдийн аюулгүй байдлыг хангахын тулд хамгаалалтын механизм нэвтрүүлэх ёстой гэж зохицуулагчид үзэж байна. Шүүхэд гаргасан нэхэмжлэл нь компаниудад хариуцлага тооцох, хохирогчдыг хамгаалах арга хэмжээг чангатгах зорилготой юм.\nЭнэ хэрэг нь хиймэл оюун ухааны зохицуулалтын талаарх дэлхийн хэмжээний хэлэлцүүлгийн нэг хэсэг болж байна. Барбадос, Энэтхэг зэрэг улсууд хиймэл оюун ухааны засаглалд хүний хяналтыг хадгалах, олон улсын аюулгүй байдлын стандарт тогтоох асуудлыг НҮБ-ын түвшинд хөндөж байгаа бөгөөд технологийн компаниудад тавих хяналт улам чангарч байна.", "textEn": "Several US states have sued Elon Musk's companies over the spread of sexualised images created by the Grok artificial intelligence chatbot, it was reported on November 26. According to the state authorities, the chatbot enabled the creation and spread of sexualised imagery of people without their consent, which they say violates the law.\nThe case has drawn attention to the misuse of artificial intelligence technology, in particular the creation of sexualised content by altering people's likenesses without permission. Experts warn that such content causes serious harm to victims' reputations and mental health and has become a new form of online abuse.\nRegulators say technology companies have a duty to prevent misuse of their AI tools and must introduce safeguards to protect users. The lawsuits aim to hold the companies accountable and strengthen measures to protect victims.\nThe case is part of a global debate on regulating artificial intelligence. Countries including Barbados and India have raised the need to keep human oversight of AI governance and set international safety standards at the United Nations, and scrutiny of technology companies is intensifying."},
  {"id": 19, "cat": "oronnutag", "time": "8 цаг", "timeEn": "8 hours", "region": "selenge", "img": "https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian%20landscapes%20and%20city%20life%2009.jpg?width=760", "title": "12-р сард Сэлэнгэ, Төв, Дундговь, Өмнөговийн нутгаар хур тунадас ахиу орно", "titleEn": "Above-average precipitation expected in Selenge, Tuv, Dundgovi and Umnugovi in December", "text": "Цаг уур, орчны шинжилгээний газраас гаргасан өвлийн улирлын ерөнхий төлөвөөр 12 дугаар сард Сэлэнгэ, Төв, Дундговь, Өмнөговийн зүүн хэсгийн нутгаар хур тунадас олон жилийн дунджаас ахиу орох төлөвтэй байгаа тухай арваннэгдүгээр сарын 25-нд мэдээллээ. Төв, зүүн аймгуудын нутгаар агаарын дундаж температур олон жилийн дунджаас хүйтэн, бусад нутгаар дунджийн орчим байх төлөвтэй байна.\nНэг, хоёрдугаар сард агаарын дундаж температур ихэнх нутгаар олон жилийн дунджаас дулаан байх бол хур тунадас нэгдүгээр сард төв, зүүн аймгуудын нутгаар, хоёрдугаар сард төвийн аймгуудын зүүн, зүүн аймгуудын ихэнх нутгаар дунджаас ахиу орох төлөвтэй байна. Иймд хур тунадас нэмэгдэж, цас зузаарах, гэнэтийн дулаарал, хүйтнээс шалтгаалан мөстөх, зам даваа халтиргаа гулгаатай болох нөхцөл бүрдэж болзошгүй юм.\nОнцгой байдлын ерөнхий газраас малчид, иргэд, тээвэрчдийг цаг агаарын гамшигт үзэгдлээс сэрэмжлүүлэх мэдээг тухай бүрт авч байхыг зөвлөлөө. Хур тунадас нэмэгдэх нь мал бэлчих, замын хөдөлгөөн, эрчим хүчний хангамжид богино хугацаанд хүндрэл учруулж болзошгүй байна.\nАгаарын дундаж температур 12 дугаар сард Хөвсгөл, Архангай, Булган, Сэлэнгэ, Төв, Хэнтий, Говьсүмбэрийн нутаг, Завханы зүүн, Баянхонгор, Дорнодын хойд, Сүхбаатарын баруун хойд хэсгээр олон жилийн дунджаас хүйтэн байх бол нийлбэр хур тунадас Хэнтий, Дорнод, Сүхбаатар, Говьсүмбэр, Дорноговийн нутаг, Сэлэнгэ, Төв, Дундговь, Өмнөговийн зүүн хэсгээр олон жилийн дунджаас ахиу орох төлөвтэй байна.", "textEn": "The National Agency for Meteorology and Environmental Monitoring's winter outlook says precipitation in December will be above the long-term average in Selenge, Tuv, Dundgovi and eastern Umnugovi provinces, it was reported on November 25. Average temperatures in December are expected to be colder than average in central and eastern provinces and near average elsewhere.\nIn January and February, average temperatures are expected to be warmer than the long-term average in most areas, while precipitation in January will be above average in central and eastern provinces, and in February in eastern central and most eastern provinces. Increased precipitation could lead to deeper snow, ice formation from sudden warming and cold snaps, and slippery roads and passes.\nThe National Emergency Management Agency has advised herders, residents and drivers to follow warnings about hazardous weather. Increased precipitation could cause short-term difficulties for livestock grazing, road transport and energy supply.\nIn December, average temperatures are expected to be colder than average in Khuvsgul, Arkhangai, Bulgan, Selenge, Tuv, Khentii and Govisumber, eastern Zavkhan, Bayankhongor, northern Dornod and north-western Sukhbaatar, while total precipitation will be above average in Khentii, Dornod, Sukhbaatar, Govisumber and Dornogovi, and in Selenge, Tuv, Dundgovi and eastern Umnugovi."}
];



function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-11-26", items:[{code:"USD", mnt:3608.65, chg:1}, {code:"EUR", mnt:3945.88, chg:1}, {code:"JPY", mnt:22.66, chg:1}, {code:"CNY", mnt:540.75, chg:-1}, {code:"KRW", mnt:2.69, chg:0}, {code:"RUB", mnt:43.83, chg:-1}, {code:"GBP", mnt:4715.96, chg:1}]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-6, code:73},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:4, code:0},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:6, code:2},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:1, code:2},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:-4, code:3},
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

